def process(raws_stations, noaa_wildfires):
    # Check all numeric columns and their ranges in RAWS
    noaa_ids = noaa_wildfires['station_verified_in_psa'].dropna().unique()
    print(f"NOAA station IDs range: {noaa_ids.min():.0f} to {noaa_ids.max():.0f}")
    print(f"NOAA sample IDs: {sorted(noaa_ids)[:10]}")

    # Check RAWS numeric columns
    numeric_cols = raws_stations.select_dtypes(include='number').columns.tolist()
    print(f"\nRAWS numeric columns: {numeric_cols}")
    for col in numeric_cols:
        vals = raws_stations[col].dropna()
        if len(vals) > 0:
            print(f"  {col}: min={vals.min():.0f}, max={vals.max():.0f}, sample={sorted(vals.unique())[:5]}")

    return pd.DataFrame({'info': ['see console']})
